ST.xhtml:p:
(*防甩轴1*)
Rtring1(CLK := g_biAntiRejection1HomeEnable OR bAntiRejection1HomeEnable OR g_bAntiRejection1HomeEnable);

IF Rtring1.Q THEN
  nHomingState1 :=1;
  g_boAntiRejection1HomeDone := FALSE;
  bAntiRejection1HomeDone := FALSE;
END_IF;

CASE nHomingState1 OF 
  0:
  nHomingState1 := 0;
  1:
  g_AntiRejection1Home.Execute := TRUE;
  g_AntiRejection1Home.Position := dHomePosition1;
  g_AntiRejection1Home.bCalibrationCam := g_bAntiRejection1Zero;
  IF nHomingMode1 =0 THEN
    g_AntiRejection1Home.HomingMode := 0;
  ELSIF nHomingMode1 = 1 THEN
    g_AntiRejection1Home.HomingMode := 5;
  ELSIF nHomingMode1 = 3 THEN
    g_AntiRejection1Home.HomingMode := 1;
  END_IF;

  IF g_AntiRejection1Home.Done THEN
    g_AntiRejection1Home.Execute := FALSE;
    g_boAntiRejection1HomeDone := TRUE;

    IF nHomingMode1 = 3 THEN
      nHomingState1 := 0;
    ELSE
      nHomingState1 := 2;
    END_IF;

  END_IF;
  IF g_bPlcPauseBuffer THEN
    nHomingState1 := 10;
  END_IF;
  IF g_AntiRejection1Home.CommandAborted OR g_AntiRejection1Home.error THEN
    nHomingState1 := 0;
    g_AntiRejection1Home.Execute := FALSE;
    g_boAntiRejection1HomeDone := FALSE;
  END_IF;
  2:
  g_AntiRejection1Abs.Execute := TRUE;
  g_AntiRejection1Abs.Position := dHomeOffset1;
  g_AntiRejection1Abs.Velocity := dHomeVel1;
  IF g_AntiRejection1Abs.Done THEN
    g_AntiRejection1Abs.Execute := FALSE;
    bAntiRejection1HomeDone := TRUE;
    g_boAntiRejection1HomeDone := TRUE;
    nHomingState1 := 0;
  END_IF;
  IF g_bPlcPauseBuffer THEN
    nHomingState1 := 11;
  END_IF;
  10:
  g_AntiRejection1Home.Execute := FALSE;
  g_AntiRejection1Stop.Execute := TRUE;
  IF g_AntiRejection1Stop.Done AND g_bPlcStartBuffer THEN
    g_AntiRejection1Stop.Execute := FALSE;
    nHomingState1 := 1;
  END_IF;
  IF g_AntiRejection1Stop.CommandAborted OR g_AntiRejection1Stop.error THEN
    g_AntiRejection1Stop.Execute := FALSE;
    nHomingState1 :=0;
  END_IF;
 11:
  g_AntiRejection1Home.Execute := FALSE;
  g_AntiRejection1Stop.Execute := TRUE;
  IF g_AntiRejection1Stop.Done AND g_bPlcStartBuffer THEN
    g_AntiRejection1Stop.Execute := FALSE;
    nHomingState1 := 2;
  END_IF;
  IF g_AntiRejection1Stop.CommandAborted OR g_AntiRejection1Stop.error THEN
    g_AntiRejection1Stop.Execute := FALSE;
    nHomingState1 :=0;
  END_IF;
END_CASE;
IF g_bPlcResetBuffer THEN
  g_AntiRejection1Home.Execute := FALSE;
  nHomingState1 :=0;
  g_AntiRejection1Rel.Execute := FALSE;
  g_AntiRejection1Stop.Execute := FALSE;
  bAntiRejection1HomeDone := TRUE;
END_IF;
